import { useRef, useState, useCallback, useEffect } from 'react';
import { isElementRtl, getLogicalScrollLeft, setLogicalScrollLeft } from './carouselScrollDirection.js';

/**
 * Custom hook for horizontal scrolling of a carousel
 *
 * Based on a configuration of numColumns, columnGap, itemWidth, and carouselWidth,
 * the hook provides callbacks for scrolling forwards and backwards.
 *
 * Scroll math uses a logical offset (0 at the first item, increasing toward later
 * items) so LTR and RTL behave the same. Browser scrollLeft is converted at the
 * DOM boundary via carouselScrollDirection helpers.
 */
const useCarouselHorizontalScroll = (shouldUseHorizontalScroll, itemWidth, carouselWidth, numColumns, columnGap, totalNumberOfItems, thresholdFromEnd, onReachedThresholdFromEnd, reportHorizontalScrollTelemetry) => {
    const currentScrollIndexRef = useRef(0);
    // Direction is refreshed in the effect and snapToItem; native scroll reads the cache.
    const isRtlRef = useRef(false);
    const directionResolvedRef = useRef(false);
    const carouselScrollRef = useRef(null);
    const [isRtl, setIsRtl] = useState(false);
    const [isScrollBackDisabled, setIsScrollBackDisabled] = useState(false);
    const [isScrollForwardDisabled, setIsScrollForwardDisabled] = useState(false);
    const [visibleRange, setVisibleRange] = useState({
        first: 0,
        last: Math.min(totalNumberOfItems - 1, numColumns - 1)
    });
    const [isScrolling, setIsScrolling] = useState(false);
    const hasReachedThresholdRef = useRef(false);
    // Update the current scroll index within the bounds of the carousel
    const updateScrollIndex = useCallback((newIndex) => {
        const maxScrollIndex = Math.max(totalNumberOfItems - numColumns, 0);
        if (newIndex < 0) {
            currentScrollIndexRef.current = 0;
        }
        else if (newIndex > maxScrollIndex) {
            currentScrollIndexRef.current = maxScrollIndex;
        }
        else {
            currentScrollIndexRef.current = newIndex;
        }
        return currentScrollIndexRef.current;
    }, [totalNumberOfItems, numColumns]);
    const checkShouldCallThresholdCallback = useCallback((logicalScrollLeft) => {
        if (!shouldUseHorizontalScroll || !onReachedThresholdFromEnd) {
            return;
        }
        if (carouselScrollRef.current && carouselWidth) {
            // Default threshold is 3x the carousel width, or the passed value if larger
            const threshold = Math.max(thresholdFromEnd ?? 0, 3 * carouselWidth);
            if (logicalScrollLeft + carouselWidth >=
                carouselScrollRef.current.scrollWidth - threshold) {
                if (!hasReachedThresholdRef.current) {
                    onReachedThresholdFromEnd();
                    hasReachedThresholdRef.current = true;
                }
            }
            else {
                hasReachedThresholdRef.current = false;
            }
        }
    }, [
        onReachedThresholdFromEnd,
        carouselScrollRef,
        carouselWidth,
        thresholdFromEnd,
        shouldUseHorizontalScroll
    ]);
    const refreshDirection = useCallback((carouselElement) => {
        const nextIsRtl = isElementRtl(carouselElement);
        isRtlRef.current = nextIsRtl;
        directionResolvedRef.current = true;
        setIsRtl(current => (current === nextIsRtl ? current : nextIsRtl));
        return nextIsRtl;
    }, []);
    const resolveDirection = useCallback((carouselElement) => {
        // One-time resolve if the effect has not run yet.
        if (!directionResolvedRef.current) {
            return refreshDirection(carouselElement);
        }
        return isRtlRef.current;
    }, [refreshDirection]);
    const syncStateFromScrollPosition = useCallback((carouselElement, logicalScrollLeft) => {
        const resolvedLogicalScrollLeft = logicalScrollLeft ??
            getLogicalScrollLeft(carouselElement, resolveDirection(carouselElement));
        const viewportWidth = carouselWidth ?? carouselElement.clientWidth;
        const itemPitch = itemWidth + (columnGap ?? 0);
        if (itemWidth > 0 && viewportWidth > 0 && itemPitch > 0 && totalNumberOfItems > 0) {
            const viewportEnd = resolvedLogicalScrollLeft + viewportWidth;
            let first = Math.floor(resolvedLogicalScrollLeft / itemPitch);
            if (first * itemPitch + itemWidth <= resolvedLogicalScrollLeft) {
                first += 1;
            }
            let last = Math.ceil(viewportEnd / itemPitch) - 1;
            if (last * itemPitch >= viewportEnd) {
                last -= 1;
            }
            const nextRange = {
                first: Math.max(0, Math.min(first, totalNumberOfItems - 1)),
                last: Math.max(-1, Math.min(last, totalNumberOfItems - 1))
            };
            setVisibleRange(currentRange => currentRange.first === nextRange.first && currentRange.last === nextRange.last
                ? currentRange
                : nextRange);
            updateScrollIndex(Math.round(resolvedLogicalScrollLeft / itemPitch));
        }
        else {
            const nextRange = {
                first: 0,
                last: Math.min(totalNumberOfItems - 1, numColumns - 1)
            };
            setVisibleRange(currentRange => currentRange.first === nextRange.first && currentRange.last === nextRange.last
                ? currentRange
                : nextRange);
        }
        const maxScrollLeft = Math.max(0, carouselElement.scrollWidth - viewportWidth);
        setIsScrollBackDisabled(resolvedLogicalScrollLeft <= 0);
        setIsScrollForwardDisabled(resolvedLogicalScrollLeft >= maxScrollLeft - 1);
        checkShouldCallThresholdCallback(resolvedLogicalScrollLeft);
    }, [
        resolveDirection,
        carouselWidth,
        itemWidth,
        columnGap,
        totalNumberOfItems,
        numColumns,
        updateScrollIndex,
        checkShouldCallThresholdCallback
    ]);
    const snapToItem = useCallback((newIndex, isUserInitiated) => {
        if (carouselScrollRef.current) {
            const carouselElement = carouselScrollRef.current;
            const rtl = refreshDirection(carouselElement);
            const currentLogicalScrollLeft = getLogicalScrollLeft(carouselElement, rtl);
            const newLogicalScrollLeft = newIndex * (itemWidth + (columnGap ?? 0));
            setLogicalScrollLeft(carouselElement, newLogicalScrollLeft, rtl);
            // Pass logical offset so sync does not re-read scrollLeft; direction already refreshed.
            syncStateFromScrollPosition(carouselElement, newLogicalScrollLeft);
            if (reportHorizontalScrollTelemetry && isUserInitiated) {
                reportHorizontalScrollTelemetry(newLogicalScrollLeft - currentLogicalScrollLeft, // scrollDistance (positive = forward)
                currentLogicalScrollLeft, // startingPosition
                carouselWidth ?? -1 // scrollAreaSize
                );
            }
        }
    }, [
        itemWidth,
        columnGap,
        refreshDirection,
        syncStateFromScrollPosition,
        carouselWidth,
        reportHorizontalScrollTelemetry
    ]);
    const layoutSnapshotRef = useRef({
        shouldUseHorizontalScroll,
        itemWidth,
        carouselWidth,
        numColumns,
        columnGap
    });
    // Item appends and new callback identities must refresh arrow and visibility
    // state from the live scroll offset. Assigning scrollLeft is only correct when
    // the layout itself changed; otherwise a swipe between tiles gets pulled back.
    useEffect(() => {
        const previousLayout = layoutSnapshotRef.current;
        const layoutChanged = previousLayout.shouldUseHorizontalScroll !== shouldUseHorizontalScroll ||
            previousLayout.itemWidth !== itemWidth ||
            previousLayout.carouselWidth !== carouselWidth ||
            previousLayout.numColumns !== numColumns ||
            previousLayout.columnGap !== columnGap;
        layoutSnapshotRef.current = {
            shouldUseHorizontalScroll,
            itemWidth,
            carouselWidth,
            numColumns,
            columnGap
        };
        const carouselElement = carouselScrollRef.current;
        if (!carouselElement) {
            directionResolvedRef.current = false;
            return;
        }
        if (layoutChanged && shouldUseHorizontalScroll) {
            snapToItem(updateScrollIndex(currentScrollIndexRef.current), false);
            return;
        }
        const rtl = refreshDirection(carouselElement);
        syncStateFromScrollPosition(carouselElement, shouldUseHorizontalScroll ? getLogicalScrollLeft(carouselElement, rtl) : 0);
    }, [
        shouldUseHorizontalScroll,
        itemWidth,
        carouselWidth,
        numColumns,
        columnGap,
        snapToItem,
        updateScrollIndex,
        refreshDirection,
        syncStateFromScrollPosition
    ]);
    const onScrollToNext = useCallback(() => {
        const newScrollIndex = updateScrollIndex(currentScrollIndexRef.current + numColumns);
        snapToItem(newScrollIndex, true);
    }, [updateScrollIndex, snapToItem, numColumns]);
    const onScrollToPrev = useCallback(() => {
        const newScrollIndex = updateScrollIndex(currentScrollIndexRef.current - numColumns);
        snapToItem(newScrollIndex, true);
    }, [updateScrollIndex, snapToItem, numColumns]);
    const onScrollHandlerThrottled = useCallback((onScrollHandler) => {
        if (!isScrolling) {
            setIsScrolling(true);
            onScrollHandler();
            // Briefly disable scrolling to prevent multiple repeated calls
            setTimeout(() => {
                setIsScrolling(false);
            }, 500);
        }
    }, [isScrolling]);
    const handleScrollBackClick = useCallback(() => {
        onScrollHandlerThrottled(onScrollToPrev);
    }, [onScrollToPrev, onScrollHandlerThrottled]);
    const handleScrollForwardClick = useCallback(() => {
        onScrollHandlerThrottled(onScrollToNext);
    }, [onScrollToNext, onScrollHandlerThrottled]);
    const handleCarouselScroll = useCallback(event => {
        const carouselElement = event.currentTarget;
        // Native scroll is the hot path — use the cached direction, not getComputedStyle.
        syncStateFromScrollPosition(carouselElement, getLogicalScrollLeft(carouselElement, resolveDirection(carouselElement)));
    }, [resolveDirection, syncStateFromScrollPosition]);
    const getIsTileVisible = useCallback((index) => {
        return index >= visibleRange.first && index <= visibleRange.last;
    }, [visibleRange]);
    return {
        carouselScrollRef,
        isRtl,
        isScrollBackDisabled: isScrollBackDisabled || isScrolling,
        isScrollForwardDisabled: isScrollForwardDisabled || isScrolling,
        handleScrollBackClick,
        handleScrollForwardClick,
        handleCarouselScroll,
        getIsTileVisible,
        firstVisibleIndex: visibleRange.first,
        lastVisibleIndex: visibleRange.last
    };
};

export { useCarouselHorizontalScroll as default };
